const BusinessBurst: React.FC<BusinessBurstProps> = ({
  backgroundColor = "#0B132B",
  transparentBackground = false,
  durationInSeconds = 1,
  primaryColor = "#00E5FF",
  secondaryColor = "#7E57C2",
  accentColor = "#FFD700",
  iconCount = 35,
  clusterSpread = 0.8,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;
  const colors = [primaryColor, secondaryColor, accentColor, "#FFFFFF"];

  // Pre-generate icon properties to ensure deterministic layout per render
  const items = useMemo(() => {
    return Array.from({ length: iconCount }).map((_, i) => {
      const angle = random(`angle${i}`) * Math.PI * 2;
      // Using Math.sqrt on the random value creates an even distribution across the circle
      // Using Math.max expands the spawn radius to cover the entire frame evenly rather than tightly clustering
      const distance =
        Math.sqrt(random(`dist${i}`)) * Math.max(width, height) * 0.6 * clusterSpread;
      
      const x = width / 2 + Math.cos(angle) * distance;
      const y = height / 2 + Math.sin(angle) * distance;
      
      const baseSize = 60 + random(`size${i}`) * 160;
      const color = colors[Math.floor(random(`color${i}`) * colors.length)];
      const path = ICONS[Math.floor(random(`icon${i}`) * ICONS.length)];
      
      // Delays mapped as ratios of the respective phases to handle variable durations dynamically
      const delayInRatio = random(`in${i}`);
      const delayOutRatio = random(`out${i}`);
      const baseRotation = random(`rot${i}`) * 360;
      
      // Sine wave offsets for hold-phase micro movements
      const pulseSpeed = 4 + random(`pspeed${i}`) * 4;
      const pulseOffset = random(`poffset${i}`) * 10;
      const rotSpeed = 6 + random(`rspeed${i}`) * 6;

      return {
        id: i,
        x,
        y,
        baseSize,
        color,
        path,
        delayInRatio,
        delayOutRatio,
        baseRotation,
        pulseSpeed,
        pulseOffset,
        rotSpeed,
      };
    });
  }, [iconCount, width, height, clusterSpread, colors]);

  const totalFrames = durationInSeconds * fps;
  const inDuration = fps * 0.35; 
  const outDuration = fps * 0.35;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      {items.map((item) => {
        // Calculate entrance timing
        const itemDelayIn = item.delayInRatio * (inDuration * 0.6);
        const inFrame = Math.max(0, frame - itemDelayIn);
        
        const scaleIn = spring({
          fps,
          frame: inFrame,
          config: { damping: 14, mass: 0.6, stiffness: 120 },
        });

        // Calculate exit timing
        const itemDelayOut = item.delayOutRatio * (outDuration * 0.6);
        const outStartFrame = totalFrames - outDuration + itemDelayOut;
        const outFrame = Math.max(0, frame - outStartFrame);
        
        const scaleOut = spring({
          fps,
          frame: outFrame,
          config: { damping: 16, mass: 0.8, stiffness: 150 },
        });

        // Subtle micro-movements during peak hold phase
        const pulse = interpolate(
          Math.sin(frame / item.pulseSpeed + item.pulseOffset),
          [-1, 1],
          [0.95, 1.05]
        );
        const hoverRot = interpolate(
          Math.sin(frame / item.rotSpeed + item.id),
          [-1, 1],
          [-8, 8]
        );

        // Combine animations
        const currentScale = scaleIn * pulse * Math.max(0, 1 - scaleOut);
        const currentRotation = item.baseRotation + hoverRot;
        const opacity = interpolate(currentScale, [0, 0.5, 1], [0, 1, 1]);

        return (
          <div
            key={item.id}
            style={{
              position: "absolute",
              left: item.x - item.baseSize / 2,
              top: item.y - item.baseSize / 2,
              width: item.baseSize,
              height: item.baseSize,
              opacity,
              transform: `scale(${currentScale}) rotate(${currentRotation}deg)`,
              transition: "none",
              filter: `drop-shadow(0px 8px 24px rgba(0, 0, 0, 0.6))`,
            }}
          >
            <svg
              width="100%"
              height="100%"
              viewBox="0 0 24 24"
              fill="none"
              xmlns="http://www.w3.org/2000/svg"
              style={{ transition: "none" }}
            >
              <path
                d={item.path}
                fill={item.color}
                stroke={backgroundColor}
                strokeWidth={0.5}
                strokeLinejoin="round"
                style={{ transition: "none" }}
              />
            </svg>
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

